{
  "findings": [
    {
      "check_id": "CKV_AZURE_25",
      "title": "Threat Detection types not set to All",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The 'disabled_alerts' list explicitly disables critical security alerts for SQL Injection and Data Exfiltration, leaving the database vulnerable to common attack vectors without notification."
    },
    {
      "check_id": "CKV_AZURE_26",
      "title": "Send Alerts To is not enabled",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The 'email_addresses' attribute is missing, meaning no specific recipients will receive email notifications when security threats are detected."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "Email service and co-administrators is not enabled",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The 'email_account_admins' attribute is missing (defaults to false), so Azure subscription administrators will not be notified of potential security breaches."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts            = []\n  retention_days             = 20\n  email_account_admins       = true\n  email_addresses            = [\"security-team@example.com\"]\n}",
  "fix_summary": "Removed disabled alerts to ensure all threat detection types are active. Added 'email_account_admins = true' and a placeholder 'email_addresses' list to ensure security alerts are sent to relevant stakeholders."
}
